<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;class AdminUserController extends Controller{public function index(Request $r){return response()->json(User::when($r->search,fn($q,$s)=>$q->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('email','like',"%$s%")))->latest()->paginate(20));}public function status(Request $r,User $user){abort_if($user->role==='admin',422,'Le compte administrateur ne peut pas être désactivé ici.');$d=$r->validate(['is_active'=>'required|boolean']);$user->update($d);if(!$user->is_active)$user->tokens()->delete();return ['data'=>$user];}}
